/**
 * Component tests for the `AddEntryModal` template cards (T18).
 *
 * The `passkey` card is the entry point of the CXF import flow, **not** a
 * template for a hand-built entry: a passkey's private key is generated by the
 * authenticator and never typed, so the card must route to the import modal and
 * must never let `handleSubmit` build a `data_type: "passkey"` data entry.
 *
 * Pinned here:
 *
 * 1. every template card is rendered, including the new `passkey` one;
 * 2. clicking `passkey` closes this modal and opens the passkey import modal —
 *    it does **not** switch to the field form;
 * 3. the other cards still open the field form (regression);
 * 4. a data entry created from a normal template is still a `DataEntry` with
 *    its own `data_type` (no `"passkey"` ever reaches the vault).
 *
 * Mocks are registered before the module under test is imported (vitest hoists
 * `vi.mock` above the imports). `waitFor` from Testing Library is unreliable
 * under bun+jsdom, so the async assertions poll with their own helper.
 */

import { configureStore } from "@reduxjs/toolkit";
import { render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { I18nextProvider } from "react-i18next";
import { Provider } from "react-redux";
import { beforeEach, describe, expect, it, vi } from "vitest";
import i18n from "../../../i18n";
import vaultReducer from "../../../redux/actions/vault";

const { mockAddEntry, mockGetInstance } = vi.hoisted(() => {
	const addEntry = vi.fn();
	return {
		mockAddEntry: addEntry,
		mockGetInstance: vi.fn(() => ({ addEntry })),
	};
});

vi.mock("../../../services/vault", () => ({
	// `redux/store.tsx` calls `VaultManager.getInstance().initialize(...)` at
	// import time, so the manager stub has to provide it too.
	VaultManager: {
		getInstance: () => ({
			getInstance: mockGetInstance,
			initialize: vi.fn(),
		}),
	},
}));

import { AddEntryModal } from "../../../components/Vault/Modals/AddEntryModal";
import { VaultModalContext } from "../../../components/Vault/VaultContext";

/** Polls until `assertion` stops throwing (bun+jsdom: no `waitFor`). */
async function pollUntil(
	assertion: () => void,
	{ timeoutMs = 2000, intervalMs = 20 } = {},
): Promise<void> {
	const deadline = Date.now() + timeoutMs;
	let lastError: unknown;
	while (Date.now() < deadline) {
		try {
			assertion();
			return;
		} catch (error) {
			lastError = error;
			await new Promise((resolve) => setTimeout(resolve, intervalMs));
		}
	}
	throw lastError;
}

function renderModal() {
	const closeAddEntryModal = vi.fn();
	const openPasskeyImport = vi.fn();
	const store = configureStore({
		reducer: { vault: vaultReducer },
		preloadedState: {
			vault: {
				vaults: [],
				currentVaultId: "vault-1",
				loading: false,
				error: null,
				providers: [],
				defaultProvider: null,
				providerStatus: {},
			},
		},
	});

	const contextValue = {
		isAddEntryModalOpen: true,
		closeAddEntryModal,
		addEntryPath: [],
		openPasskeyImport,
	} as unknown as React.ContextType<typeof VaultModalContext>;

	const utils = render(
		<Provider store={store}>
			<I18nextProvider i18n={i18n}>
				<VaultModalContext.Provider value={contextValue}>
					<AddEntryModal />
				</VaultModalContext.Provider>
			</I18nextProvider>
		</Provider>,
	);

	return { ...utils, closeAddEntryModal, openPasskeyImport };
}

/**
 * The modal lives inside `<dialog>`, which jsdom keeps out of the a11y tree:
 * role queries must pass `hidden: true` to reach its buttons.
 */
const byRole = (name: string) =>
	screen.getByRole("button", { name, hidden: true });

/**
 * A template card, found by its heading.
 *
 * The card's accessible name is its whole text content — the `t()`-translated
 * name *plus* the `<title>` of its icon and the description — so an exact
 * `name` query would have to repeat copy this test does not own. The heading is
 * unique per card and is what the user reads.
 */
function templateCard(name: string): HTMLElement {
	const heading = screen.getByRole("heading", { name, hidden: true });
	const card = heading.closest("button");
	if (!(card instanceof HTMLElement)) {
		throw new Error(`template card for "${name}" is not a button`);
	}
	return card;
}

describe("AddEntryModal template cards (T18)", () => {
	beforeEach(() => {
		vi.clearAllMocks();
		mockAddEntry.mockResolvedValue(undefined);
	});

	it("renders the passkey card next to the other templates", () => {
		renderModal();

		expect(
			templateCard(i18n.t("home:addEntry.templates.passkey")),
		).toBeInTheDocument();
		expect(
			templateCard(i18n.t("home:addEntry.templates.login")),
		).toBeInTheDocument();
		expect(
			templateCard(i18n.t("home:addEntry.templates.custom")),
		).toBeInTheDocument();
	});

	it("routes the passkey card to the import modal, not the field form", async () => {
		const user = userEvent.setup();
		const { closeAddEntryModal, openPasskeyImport } = renderModal();

		await user.click(templateCard(i18n.t("home:addEntry.templates.passkey")));

		expect(closeAddEntryModal).toHaveBeenCalledTimes(1);
		expect(openPasskeyImport).toHaveBeenCalledTimes(1);
		// The field form never opened: no entry title input, no fields editor.
		expect(screen.queryByText(i18n.t("home:addEntry.entryTitle"))).toBeNull();
		expect(screen.queryByRole("textbox", { hidden: true })).toBeNull();
	});

	it("still opens the field form for a normal template (regression)", async () => {
		const user = userEvent.setup();
		const { closeAddEntryModal, openPasskeyImport } = renderModal();

		await user.click(templateCard(i18n.t("home:addEntry.templates.login")));

		expect(
			screen.getByPlaceholderText(
				i18n.t("home:addEntry.entryTitlePlaceholder"),
			),
		).toBeInTheDocument();
		// The passkey flow is not touched by another card.
		expect(openPasskeyImport).not.toHaveBeenCalled();
		expect(closeAddEntryModal).not.toHaveBeenCalled();
	});

	it("never creates a data_type 'passkey' entry from the passkey card", async () => {
		const user = userEvent.setup();
		renderModal();

		await user.click(templateCard(i18n.t("home:addEntry.templates.passkey")));

		// No submit path was reachable: nothing was written to the vault.
		expect(mockAddEntry).not.toHaveBeenCalled();
	});

	it("creates a DataEntry with the chosen template's data_type", async () => {
		const user = userEvent.setup();
		const { closeAddEntryModal } = renderModal();

		await user.click(templateCard(i18n.t("home:addEntry.templates.login")));

		const titleInput = screen.getByPlaceholderText(
			i18n.t("home:addEntry.entryTitlePlaceholder"),
		);
		await user.type(titleInput, "Mail");
		await user.click(byRole(i18n.t("home:addEntry.addEntry")));

		await pollUntil(() => {
			expect(mockAddEntry).toHaveBeenCalledTimes(1);
		});
		const [, newEntry] = mockAddEntry.mock.calls[0];
		expect(newEntry.entry_type).toBe("entry");
		expect(newEntry.data_type).toBe("login");
		expect(newEntry.data_type).not.toBe("passkey");
		expect(closeAddEntryModal).toHaveBeenCalled();
	});
});
